import{_ as c,c as l,b as t,d as o,e as s,a as e,w as p,r as i,o as r}from"./app-DPjfhbqi.js";const d={};function u(k,n){const a=i("RouteLink");return r(),l("div",null,[n[13]||(n[13]=t('<h1 id="_02-类型系统与类型转换" tabindex="-1"><a class="header-anchor" href="#_02-类型系统与类型转换"><span>02 类型系统与类型转换</span></a></h1><p>&gt; Last Format Time：8/11/2026 21:45:36</p><p>本笔记由两个 JavaScript 教程目录中的同主题内容合并而成；全部旧知识保留在“旧笔记知识全集（按来源保留）”中，并由导航逐项索引。</p><hr><h2 id="当前前端开发关键要点" tabindex="-1"><a class="header-anchor" href="#当前前端开发关键要点"><span>当前前端开发关键要点</span></a></h2><p>&gt; [!important] 学习优先级：P0 &gt; - 区分原始类型与对象类型，理解赋值、参数传递和比较时的值语义与引用语义。 &gt; - 掌握 <code>typeof</code>、<code>instanceof</code>、<code>Array.isArray</code> 与 <code>Object.prototype.toString.call</code> 的适用边界。 &gt; - 警惕隐式类型转换、<code>NaN</code>、<code>null</code> 与 <code>undefined</code>；业务判断优先写出明确意图。 &gt; - TypeScript 只能提供静态约束，接口响应、表单和存储数据仍需要运行时校验。</p><hr><h2 id="知识点导航" tabindex="-1"><a class="header-anchor" href="#知识点导航"><span>知识点导航</span></a></h2><h3 id="现代js教程与阮一峰es6-·-1数据类型与变量-数据类型与转换-02-类型系统与类型转换-md" tabindex="-1"><a class="header-anchor" href="#现代js教程与阮一峰es6-·-1数据类型与变量-数据类型与转换-02-类型系统与类型转换-md"><span>[现代JS教程与阮一峰ES6 · 1数据类型与变量/数据类型与转换](./02 <a href="http://xn--jhq14uba832j0r4aca80gw4iv72c.md" target="_blank" rel="noopener noreferrer">类型系统与类型转换.md</a>)</span></a></h3><ul><li>数据类型与转换</li><li>数据类型</li><li>原始类型（Primitive，7 种）</li><li>对象类型（Object）</li><li>类型判断</li><li>typeof 运算符</li><li>instanceof</li><li>Object.prototype.toString.call()</li><li>其他辅助方法</li><li>原始类型的&quot;包装对象&quot;</li><li>类型转换</li><li>显式转换</li><li>隐式转换（自动发生）</li></ul><h3 id="廖雪峰教程-·-3快速入门-3-2-数据类型与变量-02-类型系统与类型转换-md" tabindex="-1"><a class="header-anchor" href="#廖雪峰教程-·-3快速入门-3-2-数据类型与变量-02-类型系统与类型转换-md"><span>[廖雪峰教程 · 3快速入门/3.2 数据类型与变量](./02 <a href="http://xn--jhq14uba832j0r4aca80gw4iv72c.md" target="_blank" rel="noopener noreferrer">类型系统与类型转换.md</a>)</span></a></h3><ul><li>数据类型与变量</li><li>数据类型</li><li>Number</li><li>字符串</li><li>布尔值</li><li>比较运算符</li><li>BigInt</li><li>null和undefined</li><li>数组</li><li>对象</li><li>变量</li><li>strict模式</li></ul><hr><h2 id="现代前端补充与纠错" tabindex="-1"><a class="header-anchor" href="#现代前端补充与纠错"><span>现代前端补充与纠错</span></a></h2><p>&gt; [!info] 修改标记 &gt; - <em>【修正】</em>：旧教程中错误、过时或容易误导的内容。 &gt; - <em>【补充】</em>：旧教程未覆盖、但当前前端开发需要掌握的内容。 &gt; - <em>【修正代码】</em>：替换或校正了旧代码示例。</p><p>&gt; [!warning] 下方保留历史原文；类型判断和隐式转换结论以本节为准。</p><h3 id="可靠的类型判断" tabindex="-1"><a class="header-anchor" href="#可靠的类型判断"><span>可靠的类型判断</span></a></h3><ul><li><em>【修正】</em> <code>typeof null === &quot;object&quot;</code> 是历史遗留；数组用 <code>Array.isArray</code>，日期等内建对象可结合品牌检查或显式 API。</li><li><em>【修正】</em> <code>instanceof</code> 沿原型链判断，跨 iframe/realm、手动改原型或自定义 <code>Symbol.hasInstance</code> 时可能不符合直觉。</li><li><em>【修正】</em> <code>Object.is</code> 与 <code>===</code> 的主要差别是 <code>NaN</code> 和正负零；业务判断默认优先 <code>===</code>，只有确实关心这些边界时用 <code>Object.is</code>。</li><li><em>【补充】</em> <code>BigInt</code> 不能与 <code>Number</code> 直接参与算术；JSON 原生也不能序列化 <code>BigInt</code>，需要约定字符串或自定义转换。</li></ul><h3 id="转换原则" tabindex="-1"><a class="header-anchor" href="#转换原则"><span>转换原则</span></a></h3><ul><li><em>【补充】</em> 避免依赖复杂的 <code>==</code> 强制转换；表单、URL、存储中的值通常都是字符串，应在数据边界显式解析并校验。</li><li><em>【补充】</em> <code>Boolean(&quot;false&quot;)</code> 为 <code>true</code>，因为非空字符串都是真值；不要把文本直接当布尔值使用。</li><li><em>【修正】</em> <code>Number(value)</code> 要求整体可转换，<code>parseInt</code>/<code>parseFloat</code> 会读取合法前缀，三者不是等价 API。</li></ul><hr><h2 id="旧笔记知识全集-按来源保留" tabindex="-1"><a class="header-anchor" href="#旧笔记知识全集-按来源保留"><span>旧笔记知识全集（按来源保留）</span></a></h2><h3 id="现代js教程与阮一峰es6-·-1数据类型与变量-数据类型与转换" tabindex="-1"><a class="header-anchor" href="#现代js教程与阮一峰es6-·-1数据类型与变量-数据类型与转换"><span>现代JS教程与阮一峰ES6 · 1数据类型与变量/数据类型与转换</span></a></h3><h5 id="数据类型与转换" tabindex="-1"><a class="header-anchor" href="#数据类型与转换"><span>数据类型与转换</span></a></h5><p>现代 JS 教程 — <a href="https://zh.javascript.info/types" target="_blank" rel="noopener noreferrer">数据类型</a> MDN — <a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Data_structures" target="_blank" rel="noopener noreferrer">JavaScript 数据类型和数据结构</a> MDN — <a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Operators/typeof" target="_blank" rel="noopener noreferrer">typeof</a></p>',25)),o("p",null,[n[5]||(n[5]=s("JavaScript 是",-1)),n[6]||(n[6]=o("strong",null,"弱类型（动态类型）语言",-1)),n[7]||(n[7]=s("：变量本身没有固定类型，赋值时才确定；运行时可自动或手动把一种类型转成另一种类型。本篇是「1 数据类型与变量」章节的总览，深入内容见子笔记：",-1)),e(a,{to:"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E4%B8%89%E4%BB%B6%E5%A5%97/JS/JavaScript/String.html"},{default:p(()=>[...n[0]||(n[0]=[s("String",-1)])]),_:1}),n[8]||(n[8]=s(" ｜ ",-1)),e(a,{to:"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E4%B8%89%E4%BB%B6%E5%A5%97/JS/JavaScript/Number.html"},{default:p(()=>[...n[1]||(n[1]=[s("Number",-1)])]),_:1}),n[9]||(n[9]=s(" ｜ ",-1)),e(a,{to:"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E4%B8%89%E4%BB%B6%E5%A5%97/JS/JavaScript/Object/"},{default:p(()=>[...n[2]||(n[2]=[s("Object",-1)])]),_:1}),n[10]||(n[10]=s(" ｜ ",-1)),e(a,{to:"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E4%B8%89%E4%BB%B6%E5%A5%97/JS/JavaScript/Arrray.html"},{default:p(()=>[...n[3]||(n[3]=[s("Arrray",-1)])]),_:1}),n[11]||(n[11]=s(" ｜ ",-1)),e(a,{to:"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E4%B8%89%E4%BB%B6%E5%A5%97/JS/JavaScript/var%20let%20const.html"},{default:p(()=>[...n[4]||(n[4]=[s("var let const",-1)])]),_:1}),n[12]||(n[12]=s("。",-1))]),n[14]||(n[14]=t(`<h5 id="数据类型" tabindex="-1"><a class="header-anchor" href="#数据类型"><span>数据类型</span></a></h5><p>JS 的值不是「原始类型」就是「对象」，共 <strong>8 种类型</strong>。其中原始类型 7 种、对象类型 1 种（但对象有多种形态）。</p><h5 id="原始类型-primitive-7-种" tabindex="-1"><a class="header-anchor" href="#原始类型-primitive-7-种"><span>原始类型（Primitive，7 种）</span></a></h5><table><thead><tr><th>类型</th><th>说明</th><th>字面量示例</th></tr></thead><tbody><tr><td><code>string</code></td><td>字符串</td><td><code>&#39;hello&#39;</code>、<code>&quot;world&quot;</code>、<code>\`template\`</code></td></tr><tr><td><code>number</code></td><td>数字（整数 + 浮点数）</td><td><code>123</code>、<code>3.14</code>、<code>NaN</code>、<code>Infinity</code></td></tr><tr><td><code>bigint</code></td><td>任意长度的整数</td><td><code>123n</code>、<code>0n</code></td></tr><tr><td><code>boolean</code></td><td>布尔</td><td><code>true</code>、<code>false</code></td></tr><tr><td><code>null</code></td><td>&quot;无 / 空 / 值未知&quot; 的特殊值</td><td><code>null</code></td></tr><tr><td><code>undefined</code></td><td>&quot;未被赋值&quot; 的特殊值</td><td><code>undefined</code></td></tr><tr><td><code>symbol</code></td><td>唯一且不可变的标识符</td><td><code>Symbol(&#39;id&#39;)</code></td></tr></tbody></table><p>补充说明：</p><ul><li><code>bigint</code> 在数字末尾加 <code>n</code>，用于超出 <code>Number.MAX_SAFE_INTEGER</code>（2⁵³−1）的整数场景，避免浮点精度丢失。</li><li><code>symbol</code> 常用于对象的「唯一属性键」，避免与已有键名冲突。</li><li><code>null</code> 与 <code>undefined</code> 是两个独立类型：<code>null</code> 是&quot;已知为空&quot;，<code>undefined</code> 是&quot;尚未赋值&quot;。</li></ul><h5 id="对象类型-object" tabindex="-1"><a class="header-anchor" href="#对象类型-object"><span>对象类型（Object）</span></a></h5><p>对象是<strong>键值对</strong>的集合，可存储多个值作为属性。除了普通对象 <code>{}</code>，还有多种&quot;形态&quot;——它们本质都是对象，但各自有专用语法和 API：</p><ul><li><code>Array</code> 数组：用 <code>[]</code> 创建，索引化的对象</li><li><code>Function</code> 函数：可调用的对象</li><li>内建对象：<code>Date</code>、<code>RegExp</code>、<code>Map</code>、<code>Set</code>、<code>Error</code>、<code>Promise</code> 等</li></ul><p>&gt; <strong>栈 vs 堆</strong>：原始类型值直接存在<strong>栈</strong>里；对象存在<strong>堆</strong>里，变量持有的是&quot;指向堆的引用&quot;（地址），所以对象叫&quot;引用类型&quot;。这解释了为什么对象赋值/传参是&quot;共享同一份&quot;，而原始类型是&quot;拷贝一份&quot;。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> a <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">let</span> b <span class="token operator">=</span> a<span class="token punctuation">;</span>       <span class="token comment">// b 拿到的是同一个引用</span></span>
<span class="line">b<span class="token punctuation">.</span>x <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>a<span class="token punctuation">.</span>x<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 2 —— a 也被改了</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">let</span> p <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">let</span> q <span class="token operator">=</span> p<span class="token punctuation">;</span>       <span class="token comment">// q 拷贝了一份值</span></span>
<span class="line">q <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>p<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 1 —— p 不受影响</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="类型判断" tabindex="-1"><a class="header-anchor" href="#类型判断"><span>类型判断</span></a></h5><h5 id="typeof-运算符" tabindex="-1"><a class="header-anchor" href="#typeof-运算符"><span>typeof 运算符</span></a></h5><p>注意 <code>typeof</code> 是<strong>操作符</strong>不是函数。括号与 <code>typeof</code> 本身无关，写不写都行：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">typeof</span> operand       <span class="token comment">// 推荐写法（操作符风格）</span></span>
<span class="line"><span class="token keyword">typeof</span><span class="token punctuation">(</span>operand<span class="token punctuation">)</span>      <span class="token comment">// 括号只是数学分组，不是函数调用</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">typeof</span> <span class="token number">123</span><span class="token punctuation">;</span>        <span class="token comment">// &#39;number&#39;</span></span>
<span class="line"><span class="token keyword">typeof</span> <span class="token number">123n</span><span class="token punctuation">;</span>       <span class="token comment">// &#39;bigint&#39;</span></span>
<span class="line"><span class="token keyword">typeof</span> <span class="token number">NaN</span><span class="token punctuation">;</span>        <span class="token comment">// &#39;number&#39;</span></span>
<span class="line"><span class="token keyword">typeof</span> <span class="token string">&#39;str&#39;</span><span class="token punctuation">;</span>      <span class="token comment">// &#39;string&#39;</span></span>
<span class="line"><span class="token keyword">typeof</span> <span class="token boolean">true</span><span class="token punctuation">;</span>       <span class="token comment">// &#39;boolean&#39;</span></span>
<span class="line"><span class="token keyword">typeof</span> <span class="token keyword">undefined</span><span class="token punctuation">;</span>  <span class="token comment">// &#39;undefined&#39;</span></span>
<span class="line"><span class="token keyword">typeof</span> <span class="token function">Symbol</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// &#39;symbol&#39;</span></span>
<span class="line"><span class="token keyword">typeof</span> Math<span class="token punctuation">.</span>abs<span class="token punctuation">;</span>   <span class="token comment">// &#39;function&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>null与部分引用类型全是object：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">typeof</span> <span class="token keyword">null</span><span class="token punctuation">;</span>       <span class="token comment">// &#39;object&#39;   ← 官方承认的历史 bug</span></span>
<span class="line"><span class="token keyword">typeof</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>         <span class="token comment">// &#39;object&#39;   ← 数组本质是对象</span></span>
<span class="line"><span class="token keyword">typeof</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span>         <span class="token comment">// &#39;object&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol><li><strong><code>typeof null === &#39;object&#39;</code></strong>：1995 年初代 JS 留下的 bug，沿用至今。<strong>永远不会修复</strong>——修了会破坏现有代码。判断 <code>null</code> 必须显式 <code>x === null</code>。</li><li><strong><code>typeof [] === &#39;object&#39;</code></strong>：数组的原型链是 <code>arr → Array.prototype → Object.prototype → null</code>，所以 <code>typeof</code> 把它当成对象。要判断数组必须用 <code>Array.isArray(x)</code> 或 <code>x instanceof Array</code>。</li></ol><h5 id="instanceof" tabindex="-1"><a class="header-anchor" href="#instanceof"><span>instanceof</span></a></h5><p>用于检测一个对象是否是某个构造函数的实例。它的底层原理是判断构造函数的 prototype 属性是否出现在该对象的原型链上。</p><table><thead><tr><th>维度</th><th><code>typeof</code></th><th><code>instanceof</code></th></tr></thead><tbody><tr><td>适合判断</td><td>原始类型</td><td>引用类型（对象、数组、自定义类）</td></tr><tr><td>原理</td><td>操作符内部硬编码类型字符串</td><td>沿原型链查找构造函数</td></tr><tr><td>对 <code>null</code></td><td>误判 <code>&#39;object&#39;</code></td><td>抛错或返回 <code>false</code></td></tr><tr><td>对 <code>[]</code></td><td>返回 <code>&#39;object&#39;</code></td><td><code>arr instanceof Array === true</code></td></tr><tr><td>跨 iframe</td><td>不受影响</td><td>失效（不同 realm 的原型不同）</td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> arr <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">typeof</span> arr<span class="token punctuation">;</span>           <span class="token comment">// &#39;object&#39;</span></span>
<span class="line">arr <span class="token keyword">instanceof</span> <span class="token class-name">Array</span><span class="token punctuation">;</span> <span class="token comment">// true</span></span>
<span class="line">Array<span class="token punctuation">.</span><span class="token function">isArray</span><span class="token punctuation">(</span>arr<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// true（推荐）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>经验法则：<strong>原始类型用 <code>typeof</code>，引用类型用 <code>instanceof</code> / <code>Array.isArray</code>。</strong></p><h5 id="object-prototype-tostring-call" tabindex="-1"><a class="header-anchor" href="#object-prototype-tostring-call"><span>Object.prototype.toString.call()</span></a></h5><p>这是目前最通用、最可靠的类型判断“终极方案”。它通过调用对象内部的 &lt;websource&gt;Class&lt;/websource&gt; 属性，能够精准识别所有内置类型15。 适用场景：任何数据类型的精确判断，包括 null、undefined 和各类引用类型。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token class-name">Object</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token string">&#39;hello&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>     <span class="token comment">// &#39;[object String]&#39;</span></span>
<span class="line"><span class="token class-name">Object</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token number">123</span><span class="token punctuation">)</span><span class="token punctuation">;</span>         <span class="token comment">// &#39;[object Number]&#39;</span></span>
<span class="line"><span class="token class-name">Object</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>        <span class="token comment">// &#39;[object Null]&#39;</span></span>
<span class="line"><span class="token class-name">Object</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token keyword">undefined</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// &#39;[object Undefined]&#39;</span></span>
<span class="line"><span class="token class-name">Object</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>          <span class="token comment">// &#39;[object Array]&#39;</span></span>
<span class="line"><span class="token class-name">Object</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Date</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// &#39;[object Date]&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>封装使用：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">function</span> <span class="token function">getType</span><span class="token punctuation">(</span><span class="token parameter">obj</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token class-name">Object</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span>obj<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span><span class="token number">8</span><span class="token punctuation">,</span> <span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="其他辅助方法" tabindex="-1"><a class="header-anchor" href="#其他辅助方法"><span>其他辅助方法</span></a></h5><ul><li>Array.isArray()</li><li>判断构造函数</li></ul><h5 id="原始类型的-包装对象" tabindex="-1"><a class="header-anchor" href="#原始类型的-包装对象"><span>原始类型的&quot;包装对象&quot;</span></a></h5><p>为什么 <code>&#39;hello&#39;.toUpperCase()</code> 能工作？字符串明明是原始类型，却能调用方法？</p><p>原因是 JS 在<strong>访问原始类型的属性或方法时</strong>，临时创建一个&quot;包装对象&quot;，调用完立即销毁。原始类型本身仍然是原始的，没有属性。</p><p>每种原始类型都有自己的包装构造函数：</p><table><thead><tr><th>原始类型</th><th>包装构造函数</th><th>示例</th></tr></thead><tbody><tr><td><code>string</code></td><td><code>String</code></td><td><code>&#39;abc&#39;.length</code> → 临时 <code>String</code> 对象</td></tr><tr><td><code>number</code></td><td><code>Number</code></td><td><code>(123).toFixed(2)</code></td></tr><tr><td><code>bigint</code></td><td><code>BigInt</code></td><td><code>(10n).toString()</code></td></tr><tr><td><code>boolean</code></td><td><code>Boolean</code></td><td><code>true.toString()</code></td></tr><tr><td><code>symbol</code></td><td><code>Symbol</code></td><td><code>Symbol(&#39;x&#39;).description</code></td></tr></tbody></table><p>&gt; <code>null</code> 和 <code>undefined</code> 没有包装对象，所以访问它们的属性会直接报错。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token string">&#39;hello&#39;</span><span class="token punctuation">.</span><span class="token function">toUpperCase</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &#39;HELLO&#39; —— 内部临时 new String(&#39;hello&#39;).toUpperCase()</span></span>
<span class="line"><span class="token keyword">null</span><span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>       <span class="token comment">// ❌ TypeError</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>这种&quot;用完即弃&quot;的机制让原始类型既轻量（只存一个值）又方便（能用方法），是 JS 类型系统的设计妥协。</p><h5 id="类型转换" tabindex="-1"><a class="header-anchor" href="#类型转换"><span>类型转换</span></a></h5><p>大多数情况下，运算符和函数会自动把值转成正确的类型：<code>alert</code> 转字符串显示、算术运算符转数字。某些场景下需要<strong>显式转换</strong>来确保正确行为。</p><h5 id="显式转换" tabindex="-1"><a class="header-anchor" href="#显式转换"><span>显式转换</span></a></h5><table><thead><tr><th>目标</th><th>函数</th><th>说明</th></tr></thead><tbody><tr><td>字符串</td><td><code>String(x)</code></td><td>任何值都能转，副作用为 <code>undefined → &#39;undefined&#39;</code>、<code>null → &#39;null&#39;</code></td></tr><tr><td>数字</td><td><code>Number(x)</code></td><td>解析失败返回 <code>NaN</code>；<code>null → 0</code>、<code>undefined → NaN</code></td></tr><tr><td>布尔</td><td><code>Boolean(x)</code></td><td>只有 6 个值转 <code>false</code>，其余全是 <code>true</code></td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token function">String</span><span class="token punctuation">(</span><span class="token number">123</span><span class="token punctuation">)</span><span class="token punctuation">;</span>         <span class="token comment">// &#39;123&#39;</span></span>
<span class="line"><span class="token function">String</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>        <span class="token comment">// &#39;null&#39;</span></span>
<span class="line"><span class="token function">Number</span><span class="token punctuation">(</span><span class="token string">&#39;123abc&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// NaN</span></span>
<span class="line"><span class="token function">Number</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>        <span class="token comment">// 0</span></span>
<span class="line"><span class="token function">Number</span><span class="token punctuation">(</span><span class="token keyword">undefined</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// NaN</span></span>
<span class="line"><span class="token function">Boolean</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>          <span class="token comment">// false</span></span>
<span class="line"><span class="token function">Boolean</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>         <span class="token comment">// true（注意：空数组是真值）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>false、0、&#39;&#39;、null、undefined、NaN</code><strong>其余全是 <code>true</code></strong>——包括 <code>[]</code>、<code>{}</code>、<code>&#39;0&#39;</code>、<code>&#39; &#39;</code>（带空格的非空字符串）。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token function">Boolean</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>          <span class="token comment">// true</span></span>
<span class="line"><span class="token function">Boolean</span><span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>          <span class="token comment">// true</span></span>
<span class="line"><span class="token function">Boolean</span><span class="token punctuation">(</span><span class="token string">&#39;0&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>         <span class="token comment">// true</span></span>
<span class="line"><span class="token function">Boolean</span><span class="token punctuation">(</span><span class="token string">&#39; &#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>         <span class="token comment">// true</span></span>
<span class="line"><span class="token function">Boolean</span><span class="token punctuation">(</span><span class="token string">&#39;false&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>     <span class="token comment">// true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="隐式转换-自动发生" tabindex="-1"><a class="header-anchor" href="#隐式转换-自动发生"><span>隐式转换（自动发生）</span></a></h5><p>JS 在这些场景会<strong>自动</strong>转换类型：</p><ul><li><strong>算术运算 <code>+ - * / %</code></strong>：<code>+</code> 遇字符串则全部转字符串，其余运算符全部转数字</li><li><strong>比较运算 <code>== &amp;gt; &amp;lt;</code></strong>：<code>==</code> 会做类型转换，<code>===</code> 不会</li><li><strong>逻辑运算 <code>&amp;&amp; || !</code></strong>：内部会转布尔再判断</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token number">1</span> <span class="token operator">+</span> <span class="token string">&#39;2&#39;</span><span class="token punctuation">;</span>        <span class="token comment">// &#39;12&#39;（+ 遇字符串）</span></span>
<span class="line"><span class="token string">&#39;5&#39;</span> <span class="token operator">-</span> <span class="token number">3</span><span class="token punctuation">;</span>        <span class="token comment">// 2（- 转数字）</span></span>
<span class="line"><span class="token boolean">true</span> <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">;</span>       <span class="token comment">// 2</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>==</code> 会做隐式转换，规则繁杂，面试常考。<strong>开发一律用 <code>===</code>，从源头规避</strong>。</p><ul><li><code>==</code> 比较中，<code>null</code> / <code>undefined</code> 只跟彼此相等，不和任何数字或字符串相等</li><li><code>NaN</code> 永远不等于自身，要判断 NaN 用 <code>Number.isNaN(x)</code> 或 <code>x !== x</code></li><li>对象与对象比较的是<strong>引用地址</strong>，内容相同但地址不同就不等</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token boolean">false</span> <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">;</span>       <span class="token comment">// true</span></span>
<span class="line"><span class="token boolean">false</span> <span class="token operator">==</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">;</span>      <span class="token comment">// true</span></span>
<span class="line"><span class="token number">0</span> <span class="token operator">==</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">;</span>          <span class="token comment">// true</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">null</span> <span class="token operator">==</span> <span class="token keyword">undefined</span><span class="token punctuation">;</span><span class="token comment">// true（唯一一组）</span></span>
<span class="line"><span class="token keyword">null</span> <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">;</span>        <span class="token comment">// false</span></span>
<span class="line"><span class="token keyword">undefined</span> <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">;</span>   <span class="token comment">// false</span></span>
<span class="line"></span>
<span class="line"><span class="token number">NaN</span> <span class="token operator">==</span> <span class="token number">NaN</span><span class="token punctuation">;</span>       <span class="token comment">// false（NaN 永远不等于自身）</span></span>
<span class="line"><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">==</span> <span class="token operator">!</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>        <span class="token comment">// true（[] == false → 0 == 0）</span></span>
<span class="line"><span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token operator">==</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span>         <span class="token comment">// false（引用比较地址，不同对象地址不同）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="廖雪峰教程-·-3快速入门-3-2-数据类型与变量" tabindex="-1"><a class="header-anchor" href="#廖雪峰教程-·-3快速入门-3-2-数据类型与变量"><span>廖雪峰教程 · 3快速入门/3.2 数据类型与变量</span></a></h3><h5 id="数据类型与变量" tabindex="-1"><a class="header-anchor" href="#数据类型与变量"><span>数据类型与变量</span></a></h5><h5 id="数据类型-1" tabindex="-1"><a class="header-anchor" href="#数据类型-1"><span>数据类型</span></a></h5><p>计算机顾名思义就是可以做数学计算的机器，因此，计算机程序理所当然地可以处理各种数值。但是，计算机能处理的远不止数值，还可以处理文本、图形、音频、视频、网页等各种各样的数据，不同的数据，需要定义不同的数据类型。在JavaScript中定义了以下几种数据类型，基本数据类型共有7种（ES6）：</p><h5 id="number" tabindex="-1"><a class="header-anchor" href="#number"><span>Number</span></a></h5><p>JavaScript不区分整数和浮点数，统一用Number表示，以下都是合法的Number类型：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token number">123</span><span class="token punctuation">;</span> <span class="token comment">// 整数123</span></span>
<span class="line"><span class="token number">0.456</span><span class="token punctuation">;</span> <span class="token comment">// 浮点数0.456</span></span>
<span class="line"><span class="token number">1.2345e3</span><span class="token punctuation">;</span> <span class="token comment">// 科学计数法表示1.2345x1000，等同于1234.5</span></span>
<span class="line"><span class="token operator">-</span><span class="token number">99</span><span class="token punctuation">;</span> <span class="token comment">// 负数</span></span>
<span class="line"><span class="token number">NaN</span><span class="token punctuation">;</span> <span class="token comment">// NaN表示Not a Number，当无法计算结果时用NaN表示</span></span>
<span class="line"><span class="token number">Infinity</span><span class="token punctuation">;</span> <span class="token comment">// Infinity表示无限大，当数值超过了JavaScript的Number所能表示的最大值时，就表示为Infinity</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>计算机由于使用二进制，所以，有时候用十六进制表示整数比较方便，十六进制用0x前缀和0-9，a-f表示，例如：<code>0xff00</code>，<code>0xa5b4c3d2</code>，等等，它们和十进制表示的数值完全一样。</p><p>Number可以直接做四则运算，规则和数学一致：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token number">1</span> <span class="token operator">+</span> <span class="token number">2</span><span class="token punctuation">;</span> <span class="token comment">// 3</span></span>
<span class="line"><span class="token punctuation">(</span><span class="token number">1</span> <span class="token operator">+</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token operator">*</span> <span class="token number">5</span> <span class="token operator">/</span> <span class="token number">2</span><span class="token punctuation">;</span> <span class="token comment">// 7.5</span></span>
<span class="line"><span class="token number">2</span> <span class="token operator">/</span> <span class="token number">0</span><span class="token punctuation">;</span> <span class="token comment">// Infinity</span></span>
<span class="line"><span class="token number">0</span> <span class="token operator">/</span> <span class="token number">0</span><span class="token punctuation">;</span> <span class="token comment">// NaN</span></span>
<span class="line"><span class="token number">10</span> <span class="token operator">%</span> <span class="token number">3</span><span class="token punctuation">;</span> <span class="token comment">// 1</span></span>
<span class="line"><span class="token number">10.5</span> <span class="token operator">%</span> <span class="token number">3</span><span class="token punctuation">;</span> <span class="token comment">// 1.5</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意<code>%</code>是求余运算。</p><p>要注意，JavaScript的Number不区分整数和浮点数，也就是说，<code>12.00 === 12</code>。（在大多数其他语言中，整数和浮点数不能直接比较）并且，JavaScript的整数最大范围不是±263，而是±253，因此，超过253的整数就可能无法精确表示：</p><h5 id="字符串" tabindex="-1"><a class="header-anchor" href="#字符串"><span>字符串</span></a></h5><p>字符串是以单引号&#39;或双引号&quot;括起来的任意文本，比如<code>&#39;abc&#39;</code>，<code>&quot;xyz&quot;</code>等等。请注意，<code>&#39;&#39;</code>或<code>&quot;&quot;</code>本身只是一种表示方式，不是字符串的一部分，因此，字符串<code>&#39;abc&#39;</code>只有<code>a</code>，<code>b</code>，<code>c</code>这3个字符。</p><h5 id="布尔值" tabindex="-1"><a class="header-anchor" href="#布尔值"><span>布尔值</span></a></h5><p>布尔值和布尔代数的表示完全一致，一个布尔值只有<code>true</code>、<code>false</code>两种值，要么是<code>true</code>，要么是<code>false</code>，可以直接用<code>true</code>、<code>false</code>表示布尔值，也可以通过布尔运算计算出来：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token boolean">true</span><span class="token punctuation">;</span> <span class="token comment">// 这是一个true值</span></span>
<span class="line"><span class="token boolean">false</span><span class="token punctuation">;</span> <span class="token comment">// 这是一个false值</span></span>
<span class="line"><span class="token number">2</span> <span class="token operator">&gt;</span> <span class="token number">1</span><span class="token punctuation">;</span> <span class="token comment">// 这是一个true值</span></span>
<span class="line"><span class="token number">2</span> <span class="token operator">&gt;=</span> <span class="token number">3</span><span class="token punctuation">;</span> <span class="token comment">// 这是一个false值</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>&amp;&amp;</code>运算是与运算，只有所有都为<code>true</code>，<code>&amp;&amp;</code>运算结果才是<code>true</code>：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token boolean">true</span> <span class="token operator">&amp;&amp;</span> <span class="token boolean">true</span><span class="token punctuation">;</span> <span class="token comment">// 这个&amp;&amp;语句计算结果为true</span></span>
<span class="line"><span class="token boolean">true</span> <span class="token operator">&amp;&amp;</span> <span class="token boolean">false</span><span class="token punctuation">;</span> <span class="token comment">// 这个&amp;&amp;语句计算结果为false</span></span>
<span class="line"><span class="token boolean">false</span> <span class="token operator">&amp;&amp;</span> <span class="token boolean">true</span> <span class="token operator">&amp;&amp;</span> <span class="token boolean">false</span><span class="token punctuation">;</span> <span class="token comment">// 这个&amp;&amp;语句计算结果为false</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>||</code>运算是或运算，只要其中有一个为<code>true</code>，<code>||</code>运算结果就是<code>true</code>：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token boolean">false</span> <span class="token operator">||</span> <span class="token boolean">false</span><span class="token punctuation">;</span> <span class="token comment">// 这个||语句计算结果为false</span></span>
<span class="line"><span class="token boolean">true</span> <span class="token operator">||</span> <span class="token boolean">false</span><span class="token punctuation">;</span> <span class="token comment">// 这个||语句计算结果为true</span></span>
<span class="line"><span class="token boolean">false</span> <span class="token operator">||</span> <span class="token boolean">true</span> <span class="token operator">||</span> <span class="token boolean">false</span><span class="token punctuation">;</span> <span class="token comment">// 这个||语句计算结果为true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>!</code>运算是非运算，它是一个单目运算符，把<code>true</code>变成<code>false</code>，<code>false</code>变成<code>true</code>：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token operator">!</span> <span class="token boolean">true</span><span class="token punctuation">;</span> <span class="token comment">// 结果为false</span></span>
<span class="line"><span class="token operator">!</span> <span class="token boolean">false</span><span class="token punctuation">;</span> <span class="token comment">// 结果为true</span></span>
<span class="line"><span class="token operator">!</span> <span class="token punctuation">(</span><span class="token number">2</span> <span class="token operator">&gt;</span> <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 结果为true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>布尔值经常用在条件判断中，比如</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">var</span> age <span class="token operator">=</span> <span class="token number">15</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>age <span class="token operator">&gt;=</span> <span class="token number">18</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">alert</span><span class="token punctuation">(</span><span class="token string">&#39;adult&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">alert</span><span class="token punctuation">(</span><span class="token string">&#39;teenager&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="比较运算符" tabindex="-1"><a class="header-anchor" href="#比较运算符"><span>比较运算符</span></a></h5><p>当我们对Number做比较时，可以通过比较运算符得到一个布尔值：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token number">2</span> <span class="token operator">&gt;</span> <span class="token number">5</span><span class="token punctuation">;</span> <span class="token comment">// false</span></span>
<span class="line"><span class="token number">5</span> <span class="token operator">&gt;=</span> <span class="token number">2</span><span class="token punctuation">;</span> <span class="token comment">// true</span></span>
<span class="line"><span class="token number">7</span> <span class="token operator">==</span> <span class="token number">7</span><span class="token punctuation">;</span> <span class="token comment">// true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>实际上，JavaScript允许对任意数据类型做比较：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token boolean">false</span> <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">;</span> <span class="token comment">// true</span></span>
<span class="line"><span class="token boolean">false</span> <span class="token operator">===</span> <span class="token number">0</span><span class="token punctuation">;</span> <span class="token comment">// false</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>要特别注意相等运算符<code>==</code>。JavaScript在设计时，有两种比较运算符： 第一种是<code>==</code>比较，它会自动转换数据类型再比较，很多时候，会得到非常诡异的结果； 第二种是<code>===</code>比较，它不会自动转换数据类型，如果数据类型不一致，返回<code>false</code>，如果一致，再比较。</p><p>由于JavaScript这个设计缺陷，_不要_使用<code>==</code>比较，始终坚持使用<code>===</code>比较。 另一个例外是<code>NaN</code>这个特殊的Number与所有其他值都不相等，包括它自己：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token number">NaN</span> <span class="token operator">===</span> <span class="token number">NaN</span><span class="token punctuation">;</span> <span class="token comment">// false</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>唯一能判断<code>NaN</code>的方法是通过<code>isNaN()</code>函数：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token function">isNaN</span><span class="token punctuation">(</span><span class="token number">NaN</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>最后要注意浮点数的相等比较：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token number">1</span> <span class="token operator">/</span> <span class="token number">3</span> <span class="token operator">===</span> <span class="token punctuation">(</span><span class="token number">1</span> <span class="token operator">-</span> <span class="token number">2</span> <span class="token operator">/</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// false</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这不是JavaScript的设计缺陷。浮点数在运算过程中会产生误差，因为计算机无法精确表示无限循环小数。要比较两个浮点数是否相等，只能计算它们之差的绝对值，看是否小于某个阈值：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">Math<span class="token punctuation">.</span><span class="token function">abs</span><span class="token punctuation">(</span><span class="token number">1</span> <span class="token operator">/</span> <span class="token number">3</span> <span class="token operator">-</span> <span class="token punctuation">(</span><span class="token number">1</span> <span class="token operator">-</span> <span class="token number">2</span> <span class="token operator">/</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">&lt;</span> <span class="token number">0.0000001</span><span class="token punctuation">;</span> <span class="token comment">// true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h5 id="bigint" tabindex="-1"><a class="header-anchor" href="#bigint"><span>BigInt</span></a></h5><p>要精确表示比253还大的整数，可以使用内置的BigInt类型，它的表示方法是在整数后加一个<code>n</code>，例如<code>9223372036854775808n</code>，也可以使用<code>BigInt()</code>把Number和字符串转换成BigInt 使用BigInt可以正常进行加减乘除等运算，结果仍然是一个BigInt，但不能把一个BigInt和一个Number放在一起运算：</p><h5 id="null和undefined" tabindex="-1"><a class="header-anchor" href="#null和undefined"><span>null和undefined</span></a></h5><p><code>null</code>表示一个“空”的值，它和<code>0</code>以及空字符串<code>&#39;&#39;</code>不同，<code>0</code>是一个数值，<code>&#39;&#39;</code>表示长度为0的字符串，而<code>null</code>表示“空”。</p><p>在其他语言中，也有类似JavaScript的<code>null</code>的表示，例如Java也用<code>null</code>，Swift用<code>nil</code>，Python用<code>None</code>表示。但是，在JavaScript中，还有一个和<code>null</code>类似的<code>undefined</code>，它表示“未定义”。</p><p>JavaScript的设计者希望用<code>null</code>表示一个空的值，而<code>undefined</code>表示值未定义。事实证明，这并没有什么卵用，区分两者的意义不大。大多数情况下，我们都应该用<code>null</code>。<code>undefined</code>仅仅在判断函数参数是否传递的情况下有用。</p><h5 id="数组" tabindex="-1"><a class="header-anchor" href="#数组"><span>数组</span></a></h5><p>数组是一组按顺序排列的集合，集合的每个值称为元素。JavaScript的数组可以包括任意数据类型。例如：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3.14</span><span class="token punctuation">,</span> <span class="token string">&#39;Hello&#39;</span><span class="token punctuation">,</span> <span class="token keyword">null</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>上述数组包含6个元素。数组用<code>[]</code>表示，元素之间用<code>,</code>分隔。</p><p>另一种创建数组的方法是通过<code>Array()</code>函数实现：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">new</span> <span class="token class-name">Array</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 创建了数组[1, 2, 3]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>然而，出于代码的可读性考虑，强烈建议直接使用<code>[]</code>。</p><h5 id="对象" tabindex="-1"><a class="header-anchor" href="#对象"><span>对象</span></a></h5><p>JavaScript的对象是一组由键-值组成的无序集合，例如：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">var</span> person <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;Bob&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">age</span><span class="token operator">:</span> <span class="token number">20</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">tags</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&#39;js&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;web&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;mobile&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">city</span><span class="token operator">:</span> <span class="token string">&#39;Beijing&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">hasCar</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">zipcode</span><span class="token operator">:</span> <span class="token keyword">null</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>JavaScript对象的键都是字符串类型，值可以是任意数据类型。上述<code>person</code>对象一共定义了6个键值对，其中每个键又称为对象的属性，例如，<code>person</code>的<code>name</code>属性为<code>&#39;Bob&#39;</code>，<code>zipcode</code>属性为<code>null</code>。</p><p>要获取一个对象的属性，我们用<code>对象变量.属性名</code>的方式：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">person<span class="token punctuation">.</span>name<span class="token punctuation">;</span> <span class="token comment">// &#39;Bob&#39;</span></span>
<span class="line">person<span class="token punctuation">.</span>zipcode<span class="token punctuation">;</span> <span class="token comment">// null</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="变量" tabindex="-1"><a class="header-anchor" href="#变量"><span>变量</span></a></h5><p>变量的概念基本上和初中代数的方程变量是一致的，只是在计算机程序中，变量不仅可以是数字，还可以是任意数据类型。</p><p>变量在JavaScript中就是用一个变量名表示，变量名是大小写英文、数字、<code>$</code>和<code>_</code>的组合，且不能用数字开头。变量名也不能是JavaScript的关键字，如<code>if</code>、<code>while</code>等。申明一个变量用<code>var</code>语句，比如：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">var</span> a<span class="token punctuation">;</span> <span class="token comment">// 申明了变量a，此时a的值为undefined</span></span>
<span class="line"><span class="token keyword">var</span> $b <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span> <span class="token comment">// 申明了变量$b，同时给$b赋值，此时$b的值为1</span></span>
<span class="line"><span class="token keyword">var</span> s_007 <span class="token operator">=</span> <span class="token string">&#39;007&#39;</span><span class="token punctuation">;</span> <span class="token comment">// s_007是一个字符串</span></span>
<span class="line"><span class="token keyword">var</span> Answer <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span> <span class="token comment">// Answer是一个布尔值true</span></span>
<span class="line"><span class="token keyword">var</span> t <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span> <span class="token comment">// t的值是null</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>变量名也可以用中文，但是，请不要给自己找麻烦。</p><p>在JavaScript中，使用等号<code>=</code>对变量进行赋值。可以把任意数据类型赋值给变量，同一个变量可以反复赋值，而且可以是不同类型的变量，但是要注意只能用<code>var</code>申明一次，例如：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">var</span> a <span class="token operator">=</span> <span class="token number">123</span><span class="token punctuation">;</span> <span class="token comment">// a的值是整数123</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token string">&#39;ABC&#39;</span><span class="token punctuation">;</span> <span class="token comment">// a变为字符串</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>这种变量本身类型不固定的语言称之为动态语言，与之对应的是静态语言。静态语言在定义变量时必须指定变量类型，如果赋值的时候类型不匹配，就会报错。例如Java是静态语言，赋值语句如下：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code class="language-java"><span class="line"><span class="token keyword">int</span> a <span class="token operator">=</span> <span class="token number">123</span><span class="token punctuation">;</span> <span class="token comment">// a是整数类型变量，类型用int申明</span></span>
<span class="line">a <span class="token operator">=</span> <span class="token string">&quot;ABC&quot;</span><span class="token punctuation">;</span> <span class="token comment">// 错误：不能把字符串赋给整型变量</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>和静态语言相比，动态语言更灵活，就是这个原因。</p><p>请不要把赋值语句的等号等同于数学的等号。比如下面的代码：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">var</span> x <span class="token operator">=</span> <span class="token number">10</span><span class="token punctuation">;</span></span>
<span class="line">x <span class="token operator">=</span> x <span class="token operator">+</span> <span class="token number">2</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>如果从数学上理解<code>x = x + 2</code>那无论如何是不成立的，在程序中，赋值语句先计算右侧的表达式<code>x + 2</code>，得到结果<code>12</code>，再赋给变量<code>x</code>。由于<code>x</code>之前的值是<code>10</code>，重新赋值后，<code>x</code>的值变成<code>12</code>。</p><h5 id="strict模式" tabindex="-1"><a class="header-anchor" href="#strict模式"><span>strict模式</span></a></h5><p>JavaScript在设计之初，为了方便初学者学习，并不强制要求用<code>var</code>申明变量。这个设计错误带来了严重的后果：如果一个变量没有通过<code>var</code>申明就被使用，那么该变量就自动被申明为全局变量：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">i <span class="token operator">=</span> <span class="token number">10</span><span class="token punctuation">;</span> <span class="token comment">// i现在是全局变量</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>在同一个页面的不同的JavaScript文件中，如果都不用<code>var</code>申明，恰好都使用了变量<code>i</code>，将造成变量<code>i</code>互相影响，产生难以调试的错误结果。</p><p>使用<code>var</code>申明的变量则不是全局变量，它的范围被限制在该变量被申明的函数体内（函数的概念将稍后讲解），同名变量在不同的函数体内互不冲突。</p><p>为了修补JavaScript这一严重设计缺陷，ECMA在后续规范中推出了strict模式，在strict模式下运行的JavaScript代码，强制通过<code>var</code>申明变量，未使用<code>var</code>申明变量就使用的，将导致运行错误。</p><p>启用strict模式的方法是在JavaScript代码的第一行写上：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token string">&#39;use strict&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这是一个字符串，不支持strict模式的浏览器会把它当做一个字符串语句执行，支持strict模式的浏览器将开启strict模式运行JavaScript。</p><p>不用<code>var</code>申明的变量会被视为全局变量，为了避免这一缺陷，所有的JavaScript代码都应该使用strict模式。我们在后面编写的JavaScript代码将全部采用strict模式。</p><p>另一种申明变量的方式是<code>let</code>，这也是现代JavaScript推荐的方式</p>`,135))])}const v=c(d,[["render",u]]),b=JSON.parse('{"path":"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E4%B8%89%E4%BB%B6%E5%A5%97/JS/JavaScript/02%20%E7%B1%BB%E5%9E%8B%E7%B3%BB%E7%BB%9F%E4%B8%8E%E7%B1%BB%E5%9E%8B%E8%BD%AC%E6%8D%A2.html","title":"02 类型系统与类型转换","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"notes/obsidian/前端/三件套/JS/JavaScript/02 类型系统与类型转换.md"}');export{v as comp,b as data};
